//! Backend abstraction layer for AI providers
//! Defines the trait and types that backends must implement

use async_trait::async_trait;
use std::fmt::Display;

/// Message from the AI backend during streaming or completion
#[derive(Debug, Clone)]
pub enum BackendMessage {
    /// A chunk of text from the streaming response
    TextDelta { delta: String },
    /// Streaming is complete
    TextDone,
    /// Final response with usage statistics
    RunComplete {
        text: String,
        input_tokens: u64,
        output_tokens: u64,
        error: Option<String>,
    },
    /// Usage statistics update (separate from run complete)
    Usage {
        input: u64,
        output: u64,
    },
    /// Connection status change
    Connected,
    Disconnected,
    /// Error occurred
    Error(String),
}

impl BackendMessage {
    /// Convert backend message to the app's internal GatewayMessage equivalent
    /// This helps bridge between the new backend and existing app code
    pub fn to_gateway_message(&self) -> crate::ai::GatewayMessage {
        match self {
            BackendMessage::TextDelta { delta } => crate::ai::GatewayMessage::TextDelta {
                delta: delta.clone(),
                session_id: String::new(), // Filled by caller
            },
            BackendMessage::TextDone => crate::ai::GatewayMessage::TextDone {
                session_id: String::new(),
            },
            BackendMessage::RunComplete {
                text,
                input_tokens,
                output_tokens,
                error,
            } => crate::ai::GatewayMessage::RunComplete {
                session_id: String::new(),
                run_id: String::new(),
                result: Some(crate::ai::AgentResult {
                    payloads: vec![crate::ai::Payload {
                        text: Some(text.clone()),
                    }],
                    meta: Some(crate::ai::AgentMeta {
                        usage: Some(crate::ai::Usage {
                            input: *input_tokens,
                            output: *output_tokens,
                            cache_read: 0,
                            total: input_tokens + output_tokens,
                        }),
                    }),
                }),
                error: error.clone(),
            },
            BackendMessage::Usage { input, output } => crate::ai::GatewayMessage::Usage {
                session_id: String::new(),
                input: *input,
                output: *output,
                cache_read: 0,
            },
            BackendMessage::Connected => crate::ai::GatewayMessage::Connected,
            BackendMessage::Disconnected => crate::ai::GatewayMessage::Disconnected,
            BackendMessage::Error(msg) => crate::ai::GatewayMessage::Error {
                message: msg.clone(),
                code: None,
            },
        }
    }
}

/// Request to send a message to the AI backend
#[derive(Debug, Clone)]
pub struct ChatRequest {
    /// Session identifier for conversation continuity
    pub session_id: String,
    /// User message content
    pub message: String,
    /// Model to use (e.g., "gpt-4", "claude-3-opus")
    pub model: Option<String>,
    /// Thinking/effort level (e.g., "low", "medium", "high")
    pub thinking: Option<String>,
    /// Agent identifier (if applicable)
    pub agent: Option<String>,
    /// Deliver mode (whether to stream response)
    pub deliver: Option<bool>,
    /// Verbose logging
    pub verbose: Option<bool>,
    /// Request timeout in seconds
    pub timeout_seconds: Option<u32>,
}

/// Backend trait - all AI providers must implement this
#[async_trait]
pub trait Backend: Send + Sync {
    /// Connect to the backend service
    async fn connect(&mut self, url: &str, token: Option<String>) -> Result<(), Box<dyn std::error::Error + Send + Sync>>;

    /// Send a chat request
    async fn send(&self, request: &ChatRequest) -> Result<(), Box<dyn std::error::Error + Send + Sync>>;

    /// Receive a message from the backend (non-blocking, returns None if no message available)
    async fn receive(&self) -> Result<Option<BackendMessage>, Box<dyn std::error::Error + Send + Sync>>;

    /// Check if connected
    async fn is_connected(&self) -> bool;

    /// Close the connection
    async fn close(&mut self) -> Result<(), Box<dyn std::error::Error + Send + Sync>>;

    /// Check backend health
    async fn health_check(&self) -> Result<bool, Box<dyn std::error::Error + Send + Sync>>;
}

/// Backend error type
#[derive(Debug, thiserror::Error)]
pub enum BackendError {
    #[error("Connection error: {0}")]
    Connection(String),
    #[error("Send error: {0}")]
    Send(String),
    #[error("Receive error: {0}")]
    Receive(String),
    #[error("Serialization error: {0}")]
    Serialization(String),
    #[error("HTTP error: {0}")]
    Http(String),
    #[error("Authentication failed")]
    Auth,
    #[error("Timeout")]
    Timeout,
    #[error("Backend unavailable")]
    Unavailable,
}

impl BackendError {
    pub fn connection(msg: impl Into<String>) -> Self {
        Self::Connection(msg.into())
    }

    pub fn send(msg: impl Into<String>) -> Self {
        Self::Send(msg.into())
    }

    pub fn receive(msg: impl Into<String>) -> Self {
        Self::Receive(msg.into())
    }
}

impl From<reqwest::Error> for BackendError {
    fn from(e: reqwest::Error) -> Self {
        Self::Http(e.to_string())
    }
}

impl From<serde_json::Error> for BackendError {
    fn from(e: serde_json::Error) -> Self {
        Self::Serialization(e.to_string())
    }
}

