pub struct GatewayConnection {
    client: reqwest::Client,
    base_url: String,
    api_key: Option<String>,
    connected: Arc<tokio::sync::Mutex<bool>>,
    message_sender: Option<mpsc::Sender<GatewayMessage>>,
    message_receiver: Option<mpsc::Receiver<GatewayMessage>>,
}

impl GatewayConnection {
    pub fn new(url: &str, token: Option<String>) -> Self {
        Self {
            client: reqwest::Client::new(),
            base_url: url.trim_end_matches('/').to_string(),
            api_key: token,
            connected: Arc::new(tokio::sync::Mutex::new(false)),
            message_sender: None,
            message_receiver: None,
        }
    }

    pub fn take_receiver(&mut self) -> Option<mpsc::Receiver<GatewayMessage>> {
        self.message_receiver.take()
    }

    pub async fn is_connected(&self) -> bool {
        *self.connected.lock().await
    }

    pub async fn connect(&mut self) -> Result<()> {
        // Create channel on first connect
        if self.message_sender.is_none() {
            let (tx, rx) = mpsc::channel(64);
            self.message_sender = Some(tx);
            self.message_receiver = Some(rx);
        }

        // Health check: GET /v1/models
        let mut headers = reqwest::header::HeaderMap::new();
        if let Some(key) = &self.api_key {
            if let Ok(val) = reqwest::header::HeaderValue::from_str(&format!("Bearer {}", key)) {
                headers.insert("Authorization", val);
            }
        }
        // Add OpenRouter attribution headers if applicable
        self.add_openrouter_headers(&mut headers);
        let health_url = format!("{}/v1/models", self.base_url);
        let resp = self.client.get(&health_url).headers(headers).send().await?;
        if !resp.status().is_success() {
            return Err(anyhow::anyhow!("Health check failed: {}", resp.status()));
        }

        *self.connected.lock().await = true;
        Ok(())
    }

    pub async fn reconnect(&mut self) -> Result<()> {
        self.close().await;
        self.connect().await
    }

    pub async fn send(&self, request: &AgentRequest) -> Result<()> {
        let sender = match &self.message_sender {
            Some(s) => s.clone(),
            None => return Err(anyhow::anyhow!("Not connected")),
        };

        // Clone all necessary data into owned types before spawning
        let client = self.client.clone();
        let base_url = self.base_url.clone();
        let api_key = self.api_key.clone();
        let session_id = request.session_id.clone();
        let user_message = request.message.clone();
        let model = request
            .agent
            .as_ref()
            .or(request.model.as_ref())
            .cloned()
            .unwrap_or_else(|| "gpt-3.5-turbo".to_string());
        let temperature = match request.thinking.as_deref() {
            Some("low") => Some(0.3),
            Some("medium") => Some(0.7),
            Some("high") => Some(1.0),
            _ => Some(0.7),
        };
        let max_tokens = request
            .timeout_seconds
            .map(|t| t as u32 * 100)
            .or(Some(2000));
        let timeout_seconds = request.timeout_seconds; // Copy (Option<u32>)
        let connected_arc = self.connected.clone();

        tokio::spawn(async move {
            // Build HTTP request
            let mut headers = reqwest::header::HeaderMap::new();
            if let Some(ref key) = api_key {
                if let Ok(val) = reqwest::header::HeaderValue::from_str(&format!("Bearer {}", key)) {
                    headers.insert("Authorization", val);
                }
            }
            headers.insert(
                "Content-Type",
                reqwest::header::HeaderValue::from_static("application/json"),
            );

            // Add OpenRouter attribution headers if applicable
            if base_url.contains("openrouter.ai") {
                if let Ok(referrer) = std::env::var("OPENROUTER_REFERRER") {
                    if let Ok(val) = reqwest::header::HeaderValue::from_str(&referrer) {
                        headers.insert("HTTP-Referer", val);
                    }
                }
                if let Ok(title) = std::env::var("OPENROUTER_SITE_TITLE") {
                    if let Ok(val) = reqwest::header::HeaderValue::from_str(&title) {
                        headers.insert("X-Title", val);
                    }
                }
            }

            let body = serde_json::json!({
                "model": model,
                "messages": [{"role": "user", "content": user_message}],
                "stream": true,
                "temperature": temperature,
                "max_tokens": max_tokens,
                "stream_options": {"include_usage": true},
            });

            let mut req_builder = client
                .post(&format!("{}/v1/chat/completions", base_url))
                .headers(headers)
                .json(&body);

            // Apply timeout if specified
            if let Some(t) = timeout_seconds {
                req_builder = req_builder.timeout(std::time::Duration::from_secs(t as u64));
            }

            let response = match req_builder.send().await {
                Ok(resp) => resp,
                Err(e) => {
                    let _ = sender
                        .send(GatewayMessage::Error(format!("Request failed: {}", e)))
                        .await;
                    *connected_arc.lock().await = false;
                    return;
                }
            };

            if !response.status().is_success() {
                let status = response.status();
                let text = response.text().await.unwrap_or_default();
                let _ = sender
                    .send(GatewayMessage::Error(format!("API error {}: {}", status, text)))
                    .await;
                *connected_arc.lock().await = false;
                return;
            }

            // Stream SSE
            let mut stream = response.bytes_stream();
            let mut full_text = String::new();
            let mut input_tokens = 0;
            let mut output_tokens = 0;
            let mut buffer = String::new();

            while let Some(chunk) = stream.next().await {
                let bytes = match chunk {
                    Ok(b) => b,
                    Err(e) => {
                        let _ = sender
                            .send(GatewayMessage::Error(format!("Stream error: {}", e)))
                            .await;
                        *connected_arc.lock().await = false;
                        break;
                    }
                };

                if let Ok(text) = String::from_utf8(bytes.to_vec()) {
                    buffer.push_str(&text);
                    // Process complete lines
                    while let Some(newline_pos) = buffer.find('\n') {
                        // Extract line as owned string before modifying buffer
                        let line = {
                            let (line_part, _rest) = buffer.split_at(newline_pos);
                            line_part.trim().to_string()
                        };
                        // Remove processed line from buffer
                        buffer = buffer[newline_pos + 1..].to_string();

                        if line.starts_with("data: ") {
                            let data = line[6..].trim();
                            if data == "[DONE]" {
                                break;
                            }
                            if let Ok(json) = serde_json::from_str::<serde_json::Value>(data) {
                                // Extract delta content
                                if let Some(choices) = json.get("choices").and_then(|c| c.as_array()) {
                                    for choice in choices {
                                        if let Some(delta) = choice.get("delta") {
                                            if let Some(content) = delta.get("content").and_then(|c| c.as_str()) {
                                                let _ = sender
                                                    .send(GatewayMessage::TextDelta {
                                                        session_id: session_id.clone(),
                                                        delta: content.to_string(),
                                                    })
                                                    .await;
                                                full_text.push_str(content);
                                            }
                                        }
                                    }
                                }
                                // Extract usage if present
                                if let Some(usage) = json.get("usage") {
                                    if let Some(i) = usage.get("prompt_tokens").and_then(|t| t.as_u64()) {
                                        input_tokens = i;
                                    }
                                    if let Some(o) = usage.get("completion_tokens").and_then(|t| t.as_u64()) {
                                        output_tokens = o;
                                    }
                                    if input_tokens > 0 || output_tokens > 0 {
                                        let _ = sender
                                            .send(GatewayMessage::Usage {
                                                input: input_tokens,
                                                output: output_tokens,
                                            })
                                            .await;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Signal completion
            let _ = sender
                .send(GatewayMessage::TextDone {
                    session_id: session_id.clone(),
                })
                .await;

            let _ = sender
                .send(GatewayMessage::RunComplete {
                    session_id,
                    text: full_text,
                    input_tokens,
                    output_tokens,
                    error: None,
                })
                .await;
        });

        Ok(())
    }

    pub async fn close(&mut self) {
        *self.connected.lock().await = false;
        // Keep message_sender alive to maintain forwarder task
        // message_receiver is already taken, no need to clear
    }

    pub fn set_token(&mut self, token: Option<String>) {
        self.api_key = token;
    }

    // Check if we're connecting to OpenRouter
    fn is_openrouter(&self) -> bool {
        self.base_url.contains("openrouter.ai")
    }

    // Add OpenRouter attribution headers if environment variables are set
    fn add_openrouter_headers(&self, headers: &mut reqwest::header::HeaderMap) {
        if !self.is_openrouter() {
            return;
        }
        // OpenRouter optional headers for attribution
        if let Ok(referrer) = std::env::var("OPENROUTER_REFERRER") {
            if let Ok(val) = reqwest::header::HeaderValue::from_str(&referrer) {
                headers.insert("HTTP-Referer", val);
            }
        }
        if let Ok(title) = std::env::var("OPENROUTER_SITE_TITLE") {
            if let Ok(val) = reqwest::header::HeaderValue::from_str(&title) {
                headers.insert("X-Title", val);
            }
        }
    }
}

