    pub id: String,
    pub pricing: ModelPricing,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct ModelsResponse {
    pub data: Vec<OpenRouterModel>,
}

/// Convert OpenRouter's per-token price string to per-million f64.
/// OpenRouter typically returns prices like "0.0000001" (USD per token).
pub fn per_token_to_per_million(price_str: &str) -> f64 {
    price_str.parse::<f64>().unwrap_or(0.0) * 1_000_000.0
}

/// Fetch the model list from OpenRouter and find rates for the specified model.
/// Returns:
///   Ok(Some((input_rate, output_rate))) if model is found
///   Ok(None) if model is not in the list
///   Err(_) on network or parsing error
pub async fn fetch_rate_for_model(
    api_key: Option<&str>,
    base_url: &str,
    model_id: &str,
) -> Result<Option<(f64, f64)>> {
    // Build the models endpoint URL
    let models_url = format!("{}/v1/models", base_url);

    // Build request headers
    let mut headers = reqwest::header::HeaderMap::new();
    if let Some(key) = api_key {
        if let Ok(val) = reqwest::header::HeaderValue::from_str(&format!("Bearer {}", key)) {
            headers.insert(reqwest::header::AUTHORIZATION, val);
        }
    }

    // Execute the request
    let client = reqwest::Client::new();
    let response = client
        .get(&models_url)
        .headers(headers)
        .send()
        .await?;

    if !response.status().is_success() {
        anyhow::bail!("Models API request failed: {}", response.status());
    }

    let models_response: ModelsResponse = response.json().await?;

    // Try to find the exact model ID
    let model = models_response
        .data
        .iter()
        .find(|m| m.id == model_id)
        .cloned();

    if let Some(model) = model {
        let input_rate = per_token_to_per_million(&model.pricing.prompt);
        let output_rate = per_token_to_per_million(&model.pricing.completion);
        Ok(Some((input_rate, output_rate)))
    } else {
        Ok(None)
    }
}

/// Get current Unix timestamp in seconds
pub fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_per_token_to_per_million() {
        fn assert_approx(a: f64, b: f64) {
            assert!((a - b).abs() < 1e-9, "expected {} ≈ {}", b, a);
        }
        assert_approx(per_token_to_per_million("0.0000001"), 0.1);
        assert_approx(per_token_to_per_million("0.000001"), 1.0);
        assert_approx(per_token_to_per_million("0.00001"), 10.0);
        assert_approx(per_token_to_per_million("0.0001"), 100.0);
        assert_approx(per_token_to_per_million("0.001"), 1000.0);
        assert_approx(per_token_to_per_million("0"), 0.0);
        assert_approx(per_token_to_per_million("invalid"), 0.0);
    }
}

