    total_tokens: u64,
}

#[derive(Debug, Deserialize)]
struct ChatCompletionResponse {
    id: String,
    choices: Vec<ResponseChoice>,
    usage: Option<Usage>,
}

#[derive(Debug, Deserialize)]
struct ResponseChoice {
    message: Option<ResponseMessage>,
    finish_reason: Option<String>,
}

#[derive(Debug, Deserialize)]
struct ResponseMessage {
    content: Option<String>,
    role: String,
}

impl OpenAIBackend {
    pub fn new(base_url: &str, api_key: Option<String>) -> Self {
        let client = Client::new();
        Self {
            client,
            base_url: base_url.trim_end_matches('/').to_string(),
            api_key,
            message_receiver: Arc::new(Mutex::new(None)),
            connected: Arc::new(Mutex::new(false)),
        }
    }

    /// Build the full chat completions endpoint URL
    fn chat_url(&self) -> String {
        format!("{}/v1/chat/completions", self.base_url)
    }

    /// Build the models endpoint URL (for health check)
    fn models_url(&self) -> String {
        format!("{}/v1/models", self.base_url)
    }

    /// Parse SSE data lines into JSON
    fn parse_sse_data(line: &str) -> Option<serde_json::Value> {
        if line.starts_with("data: ") {
            let data = line[6..].trim();
            if data == "[DONE]" {
                return None;
            }
            serde_json::from_str(data).ok()
        } else {
            None
        }
    }

    /// Spawn a task to handle streaming response and send messages to channel
    async fn spawn_stream_handler(
        &self,
        mut response: reqwest::Response,
        msg_tx: mpsc::Sender<BackendMessage>,
    ) -> Result<(), BackendError> {
        let buffer = Arc::new(Mutex::new(String::new()));
        let buffer_clone = buffer.clone();

        tokio::spawn(async move {
            let mut stream = response.bytes_stream();
            let mut buf = String::new();

            while let Some(chunk) = stream.next().await {
                match chunk {
                    Ok(bytes) => {
                        if let Ok(text) = String::from_utf8(bytes.to_vec()) {
                            buf.push_str(&text);
                            // Process complete SSE events
                            while let Some(newline_pos) = buf.find('\n') {
                                let line = buf[..newline_pos].trim();
                                if !line.is_empty() {
                                    if let Some(json) = Self::parse_sse_data(line) {
                                        if let Ok(chunk) = serde_json::from_value::<ChatCompletionChunk>(json) {
                                            for choice in chunk.choices {
                                                if let Some(delta) = choice.delta {
                                                    if let Some(content) = delta.content {
                                                        let _ = msg_tx.send(BackendMessage::TextDelta { delta: content }).await;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                buf = buf[newline_pos + 1..].to_string();
                            }
                        }
                    }
                    Err(_) => break,
                }
            }
            // Signal completion
            let _ = msg_tx.send(BackendMessage::TextDone).await;
        });

        Ok(())
    }
}

#[async_trait]
impl Backend for OpenAIBackend {
    async fn connect(&mut self, _url: &str, token: Option<String>) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        // For OpenAI, we just store the token; connection is lazy on first request
        if let Some(t) = token {
            self.api_key = Some(t);
        }
        *self.connected.lock().await = true;
        Ok(())
    }

    async fn send(&self, request: &ChatRequest) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        // Build messages array - in a real app, you'd include conversation history
        let messages = vec![ChatMessage {
            role: "user".to_string(),
            content: request.message.clone(),
        }];

        // Determine model: use request.agent as model, then request.model, then fallback
        let model = request
            .agent
            .as_ref()
            .or(request.model.as_ref())
            .closestring()
            .unwrap_or_else(|| "gpt-3.5-turbo".to_string());

        let req_body = ChatCompletionRequest {
            model: model.clone(),
            messages,
            stream: true, // Always stream for consistency
            temperature: match request.thinking.as_deref() {
                Some("low") => Some(0.3),
                Some("medium") => Some(0.7),
                Some("high") => Some(1.0),
                _ => Some(0.7),
            },
            max_tokens: request.timeout_seconds.map(|t| t as u32 * 100).or(Some(2000)),
        };

        let mut headers = reqwest::header::HeaderMap::new();
        if let Some(ref key) = self.api_key {
            headers.insert(
                "Authorization",
                reqwest::header::HeaderValue::from_str(&format!("Bearer {}", key))?,
            );
        }
        headers.insert("Content-Type", reqwest::header::HeaderValue::from_static("application/json"));

        let (msg_tx, msg_rx) = mpsc::channel(64);
        *self.message_receiver.lock().await = Some(msg_rx);

        // Send request
        let response = self
            .client
            .post(&self.chat_url())
            .headers(headers)
            .json(&req_body)
            .send()
            .await?;

        if !response.status().is_success() {
            let status = response.status();
            let text = response.text().await.unwrap_or_default();
            return Err(BackendError::Http(format!("API error {}: {}", status, text)).into());
        }

        // Spawn stream handler
        self.spawn_stream_handler(response, msg_tx).await?;

        Ok(())
    }

    async fn receive(&self) -> Result<Option<BackendMessage>, Box<dyn std::error::Error + Send + Sync>> {
        if let Some(rx) = &mut *self.message_receiver.lock().await {
            match rx.recv().await {
                Some(msg) => Ok(Some(msg)),
                None => Ok(None),
            }
        } else {
            Ok(None)
        }
    }

    async fn is_connected(&self) -> bool {
        *self.connected.lock().await
    }

    async fn close(&mut self) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        *self.message_receiver.lock().await = None;
        *self.connected.lock().await = false;
        Ok(())
    }

    async fn health_check(&self) -> Result<bool, Box<dyn std::error::Error + Send + Sync>> {
        let mut headers = reqwest::header::HeaderMap::new();
        if let Some(ref key) = self.api_key {
            headers.insert(
                "Authorization",
                reqwest::header::HeaderValue::from_str(&format!("Bearer {}", key))?,
            );
        }

        match self.client.get(&self.models_url()).headers(headers).send().await {
            Ok(resp) => Ok(resp.status().is_success()),
            Err(_) => Ok(false),
        }
    }
}

/// Create a new OpenAI-compatible backend
pub fn create_backend(
    base_url: &str,
    api_key: Option<String>,
) -> impl Backend {
    OpenAIBackend::new(base_url, api_key)
}

