use crate::app::{App, Focus, InputMode, UsageMode, COMMANDS};
use crossterm::event::{Event, KeyCode, KeyEvent, KeyEventKind};

pub fn handle_events(app: &mut App, event: Event) -> std::io::Result<bool> {
    match event {
        Event::Key(key) if key.kind == KeyEventKind::Press => {
            handle_key_event(app, key);
        }
        _ => {}
    }
    Ok(false)
}

fn handle_key_event(app: &mut App, key: KeyEvent) {
    // API key input modal takes priority
    if app.showing_api_key_input {
        handle_api_key_modal_key(app, key);
        return;
    }

    // Command palette mode intercepts navigation/selection keys first
    if app.showing_command_palette {
        if handle_command_palette_key(app, key) {
            return; // Key fully handled by palette
        }
    }

    // Try to find a matching action from keybindings
    if let Some(action) = find_action(app, &key) {
        execute_action(app, &action, &key);
        // After action execution, update palette state (e.g., backspace may have changed input)
        update_command_palette_after_input_change(app);
        return;
    }

    // Implicit default: character insertion for any printable char
    if let KeyCode::Char(c) = key.code {
        if app.focus == Focus::Input && !app.is_streaming() {
            app.input.insert(app.input_cursor, c);
            app.input_cursor += 1;
        }
    }

    // After any input change, update command palette state
    update_command_palette_after_input_change(app);
}

/// Handle keys when the command palette is showing.
/// Returns true if the key was fully handled and no further processing should occur.
fn handle_command_palette_key(app: &mut App, key: KeyEvent) -> bool {
    match key.code {
        KeyCode::Up => {
            let commands = get_filtered_commands(&app.command_filter);
            if !commands.is_empty() {
                app.command_selection =
                    (app.command_selection + commands.len() - 1) % commands.len();
            }
            true
        }
        KeyCode::Down => {
            let commands = get_filtered_commands(&app.command_filter);
            if !commands.is_empty() {
                app.command_selection = (app.command_selection + 1) % commands.len();
            }
            true
        }
        KeyCode::Enter => {
            let commands = get_filtered_commands(&app.command_filter);
            if let Some((cmd, _)) = commands.get(app.command_selection) {
                app.input = cmd.to_string();
                app.input_cursor = cmd.len();
                app.showing_command_palette = false;
                app.command_filter.clear();
                app.command_selection = 0;
            }
            true
        }
        KeyCode::Esc => {
            app.showing_command_palette = false;
            app.command_filter.clear();
            app.command_selection = 0;
            true
        }
        _ => false, // Allow other keys (char, backspace, cursor moves) to be processed normally
    }
}

/// Handle keys when API key input modal is active.
fn handle_api_key_modal_key(app: &mut App, key: KeyEvent) {
    match key.code {
        KeyCode::Char(c) => {
            app.api_key_input.insert(app.api_key_cursor, c);
            app.api_key_cursor += 1;
        }
        KeyCode::Backspace => {
            if app.api_key_cursor > 0 {
                app.api_key_input.remove(app.api_key_cursor - 1);
                app.api_key_cursor -= 1;
            }
        }
        KeyCode::Esc => {
            // Cancel API key input
            app.showing_api_key_input = false;
            app.api_key_input.clear();
            app.api_key_cursor = 0;
            app.api_key_error = None;
            app.status_message = "API key input cancelled".to_string();
        }
        KeyCode::Enter => {
            // Save API key
            if app.api_key_input.trim().is_empty() {
                app.api_key_error = Some("API key cannot be empty".to_string());
            } else {
                app.api_key = app.api_key_input.trim().to_string();
                app.api_key_needs_sync = true;
                app.showing_api_key_input = false;
                app.api_key_input.clear();
                app.api_key_cursor = 0;
                app.api_key_error = None;
                app.status_message = "API key saved - reconnecting...".to_string();
            }
        }
        KeyCode::Left => {
            if app.api_key_cursor > 0 {
                app.api_key_cursor -= 1;
            }
        }
        KeyCode::Right => {
            if app.api_key_cursor < app.api_key_input.len() {
                app.api_key_cursor += 1;
            }
        }
        KeyCode::Home => {
            app.api_key_cursor = 0;
        }
        KeyCode::End => {
            app.api_key_cursor = app.api_key_input.len();
        }
        _ => {}
    }
}

/// Update command palette visibility and filter based on current input.
/// Should be called after any change to app.input.
fn update_command_palette_after_input_change(app: &mut App) {
    if app.input.starts_with('/') {
        let filter = if let Some(space_idx) = app.input.find(' ') {
            &app.input[..space_idx]
        } else {
            &app.input
        };
        if !app.showing_command_palette {
            app.showing_command_palette = true;
            app.command_filter = filter.to_string();
            app.command_selection = 0;
        } else {
            // Update filter and reset selection if the command part changed
            if app.command_filter != filter {
                app.command_filter = filter.to_string();
                app.command_selection = 0;
            }
        }
    } else {
        app.showing_command_palette = false;
        app.command_filter.clear();
        app.command_selection = 0;
    }
}

/// Get the list of commands that match the current filter.
fn get_filtered_commands(filter: &str) -> Vec<(&'static str, &'static str)> {
    if filter.is_empty() || filter == "/" {
        return COMMANDS.to_vec();
    }
    COMMANDS
        .iter()
        .filter(|(cmd, _)| cmd.starts_with(filter))
        .copied()
        .collect()
}

fn normalize_key_event(key: &KeyEvent) -> (Vec<String>, String) {
    let mut modifiers = Vec::new();
    if key
        .modifiers
        .contains(crossterm::event::KeyModifiers::CONTROL)
    {
        modifiers.push("Ctrl".to_string());
    }
    if key.modifiers.contains(crossterm::event::KeyModifiers::ALT) {
        modifiers.push("Alt".to_string());
    }
    if key
        .modifiers
        .contains(crossterm::event::KeyModifiers::SHIFT)
    {
        modifiers.push("Shift".to_string());
    }
    if key
        .modifiers
        .contains(crossterm::event::KeyModifiers::SUPER)
    {
        modifiers.push("Super".to_string());
    }
    modifiers.sort();

    let key_str = match key.code {
        KeyCode::Char(c) => c.to_string().to_uppercase(),
        KeyCode::Enter => "Enter".to_string(),
        KeyCode::Esc => "Esc".to_string(),
        KeyCode::Tab => "Tab".to_string(),
        KeyCode::Backspace => "Backspace".to_string(),
        KeyCode::Delete => "Delete".to_string(),
        KeyCode::Insert => "Insert".to_string(),
        KeyCode::Home => "Home".to_string(),
        KeyCode::End => "End".to_string(),
        KeyCode::Up => "Up".to_string(),
        KeyCode::Down => "Down".to_string(),
        KeyCode::Left => "Left".to_string(),
        KeyCode::Right => "Right".to_string(),
        KeyCode::F(n) => format!("F{}", n),
        _ => return (modifiers, "".to_string()), // Unhandled key type
    };

    (modifiers, key_str)
}

fn find_action(app: &App, key: &KeyEvent) -> Option<String> {
    let (norm_mods, norm_key) = normalize_key_event(key);
    if norm_key.is_empty() {
        return None;
    }

    for (action, bindings) in &app.keybindings {
        for binding in bindings {
            let mut binding_mods = binding.modifiers.clone();
            binding_mods.sort();
            if binding_mods == norm_mods && binding.key == norm_key {
                return Some(action.clone());
            }
        }
    }
    None
}

fn execute_action(app: &mut App, action: &str, _key: &KeyEvent) {
    // Block most actions during streaming, except quit-related ones
    if app.is_streaming() && !matches!(action, "escape" | "force_quit") {
        return;
    }

    match action {
        "escape" => {
            if app.editing_message.is_some() {
                app.cancel_editing();
                app.status_message = "Edit cancelled".to_string();
            } else if app.error.is_some() {
                app.clear_error();
            } else {
                app.running = false;
            }
        }
        "force_quit" => {
            app.running = false;
        }
        "focus_next" => {
            app.cycle_focus();
        }
        "cycle_theme" => {
            app.cycle_theme();
            app.status_message = format!("Theme: {}", app.theme_name);
        }
        "toggle_multiline" => {
            app.toggle_input_mode();
            app.status_message = format!(
                "Input mode: {}",
                match app.input_mode {
                    InputMode::SingleLine => "single-line",
                    InputMode::MultiLine => "multi-line",
                }
            );
        }
        "edit_last" => {
            if let Some(idx) = app.get_user_message_index(-1) {
                app.start_editing(idx);
                app.status_message = "Editing message (Enter: save, Esc: cancel)".to_string();
            }
        }
        "insert_newline" => {
            if app.focus == Focus::Input && app.input_mode == InputMode::MultiLine {
                app.input.insert(app.input_cursor, '\n');
                app.input_cursor += 1;
            }
        }
        "scroll_up" => {
            if app.focus == Focus::Chat {
                app.scroll_up();
            }
        }
        "scroll_down" => {
            if app.focus == Focus::Chat {
                app.scroll_down();
            }
        }
        "enter" => {
            if app.editing_message.is_some() {
                if let Some(idx) = app.editing_message {
                    let new_content = app.input.clone();
                    app.edit_message(idx, &new_content);
                    app.cancel_editing();
                    app.status_message = "Message updated".to_string();
                }
            } else if app.focus == Focus::Input && !app.input.is_empty() {
                let input = app.input.clone();
                if input.starts_with('/') {
                    handle_command(app, &input);
                } else {
                    app.pending_message = Some(input);
                }
                app.input.clear();
                app.input_cursor = 0;
            }
        }
        "backspace" => {
            if app.focus == Focus::Input && app.input_cursor > 0 {
                app.input_cursor -= 1;
                app.input.remove(app.input_cursor);
            }
        }
        "delete" => {
            if app.focus == Focus::Input && app.input_cursor < app.input.len() {
                app.input.remove(app.input_cursor);
            }
        }
        "cursor_left" => {
            if app.focus == Focus::Input && app.input_cursor > 0 {
                app.input_cursor -= 1;
            }
        }
        "cursor_right" => {
            if app.focus == Focus::Input && app.input_cursor < app.input.len() {
                app.input_cursor += 1;
            }
        }
        "cursor_home" => {
            if app.focus == Focus::Input {
                app.input_cursor = 0;
            }
        }
        "cursor_end" => {
            if app.focus == Focus::Input {
                app.input_cursor = app.input.len();
            }
        }
        _ => {}
    }
}

fn handle_command(app: &mut App, input: &str) {
    let parts: Vec<&str> = input.split_whitespace().collect();
    if parts.is_empty() {
        return;
    }

    let cmd = parts[0].to_lowercase();
    let args = &parts[1..];

    match cmd.as_str() {
        "/new" | "/reset" => {
            app.messages.clear();
            app.session_id = format!("session-{}", chrono::Local::now().format("%Y%m%d%H%M%S"));
            app.tokens_used = 0;
            app.cost_usd = 0.0;
            app.add_message("system", "Session reset. Starting fresh.");
            app.status_message = format!("Session: {}", app.session_id);
        }
        "/clear" => {
            app.messages.clear();
            app.status_message = "Chat cleared".to_string();
        }
        "/session" => {
            if let Some(&id) = args.first() {
                app.session_id = id.to_string();
                app.messages.clear();
                app.tokens_used = 0;
                app.cost_usd = 0.0;
                app.add_message("system", &format!("Switched to session: {}", id));
                app.status_message = format!("Session: {}", id);
            } else {
                app.add_message(
                    "system",
                    &format!("Current session: {}\nUsage: /session <id>", app.session_id),
                );
            }
        }
        "/sessions" => {
            // Not directly supported by OpenAI API - show placeholder
            app.add_message("system", "Session listing not available with OpenAI backend. Each conversation is independent.");
        }
        "/history" => {
            app.add_message("system", "Loading session history...");
            app.pending_command = Some("/history".to_string());
        }
        "/agent" => {
            if let Some(&id) = args.first() {
                app.agent_id = Some(id.to_string());
                app.add_message("system", &format!("Agent set to: {}", id));
                app.status_message = format!("Agent: {}", id);
            } else if let Some(ref agent) = app.agent_id {
                app.add_message(
                    "system",
                    &format!("Current agent: {}\nUsage: /agent <id>", agent),
                );
            } else {
                app.add_message(
                    "system",
                    "No agent selected (using default)\nUsage: /agent <id>",
                );
            }
        }
        "/model" => {
            if let Some(&m) = args.first() {
                app.model = Some(m.to_string());
                app.add_message("system", &format!("Model set to: {}", m));
                app.status_message = format!("Model: {}", m);
            } else {
                let model = app.model.as_deref().unwrap_or("default");
                app.add_message(
                    "system",
                    &format!("Current model: {}\nUsage: /model <name>", model),
                );
            }
        }
        "/think" => {
            if let Some(&level) = args.first() {
                match level {
                    "off" | "minimal" | "low" | "medium" | "high" | "xhigh" => {
                        app.thinking_level = level.to_string();
                        app.status_message = format!("Thinking: {}", level);
                        app.add_message("system", &format!("Thinking level set to: {}", level));
                    }
                    _ => {
                        app.add_message(
                            "system",
                            "Invalid level. Use: off, minimal, low, medium, high, xhigh",
                        );
                    }
                }
            } else {
                app.add_message(
                    "system",
                    &format!(
                        "Thinking: {}\nUsage: /think <off|minimal|low|medium|high|xhigh>",
                        app.thinking_level
                    ),
                );
            }
        }
        "/deliver" => {
            app.deliver = !app.deliver;
            app.status_message = format!("Deliver: {}", if app.deliver { "on" } else { "off" });
            app.add_message(
                "system",
                &format!(
                    "Deliver mode {} - replies will {}be sent to the channel",
                    if app.deliver { "enabled" } else { "disabled" },
                    if app.deliver { "" } else { "not " }
                ),
            );
        }
        "/verbose" => {
            if let Some(&mode) = args.first() {
                match mode {
                    "on" => app.verbose = true,
                    "off" => app.verbose = false,
                    _ => {}
                }
            } else {
                app.verbose = !app.verbose;
            }
            app.status_message = format!("Verbose: {}", if app.verbose { "on" } else { "off" });
            app.add_message(
                "system",
                &format!("Verbose mode: {}", if app.verbose { "on" } else { "off" }),
            );
        }
        "/usage" => {
            if let Some(&mode) = args.first() {
                match mode {
                    "off" => app.usage_mode = UsageMode::Off,
                    "tokens" => app.usage_mode = UsageMode::Tokens,
                    "full" => app.usage_mode = UsageMode::Full,
                    _ => {
                        app.add_message("system", "Usage: /usage <off|tokens|full>");
                        return;
                    }
                }
                app.add_message("system", &format!("Usage display: {}", mode));
            } else {
                let mode_str = match app.usage_mode {
                    UsageMode::Off => "off",
                    UsageMode::Tokens => "tokens",
                    UsageMode::Full => "full",
                };
                let mut info = format!(
                    "Usage display: {}\nTokens: {}/{} ({:.1}%)\nContext window: {} tokens",
                    mode_str,
                    app.tokens_used,
                    app.tokens_max,
                    app.token_percent(),
                    app.tokens_max
                );
                if app.cost_usd > 0.0 {
                    info.push_str(&format!("\nCost: ${:.4}", app.cost_usd));
                }
                app.add_message("system", &info);
            }
        }
        "/cost" => {
            if app.cost_usd > 0.0 {
                app.add_message("system", &format!("Session cost: ${:.4}", app.cost_usd));
            } else {
                app.add_message(
                    "system",
                    "Cost tracking not available (provider may not report pricing)",
                );
            }
        }
        "/timeout" => {
            if let Some(&secs) = args.first() {
                if let Ok(seconds) = secs.parse::<u32>() {
                    app.timeout_seconds = Some(seconds);
                    app.add_message("system", &format!("Timeout set to {} seconds", seconds));
                } else {
                    app.add_message("system", "Usage: /timeout <seconds>");
                }
            } else {
                let current = app
                    .timeout_seconds
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "default (600s)".to_string());
                app.add_message(
                    "system",
                    &format!("Timeout: {}\nUsage: /timeout <seconds>", current),
                );
            }
        }
        "/activation" => {
            if let Some(&mode) = args.first() {
                match mode {
                    "mention" | "always" => {
                        app.activation_mode = mode.to_string();
                        app.add_message("system", &format!("Activation mode: {}", mode));
                    }
                    _ => {
                        app.add_message("system", "Usage: /activation <mention|always>");
                    }
                }
            } else {
                app.add_message(
                    "system",
                    &format!(
                        "Activation: {}\nUsage: /activation <mention|always>",
                        app.activation_mode
                    ),
                );
            }
        }
        "/restart" => {
            app.add_message("system", "Restarting gateway...");
            app.pending_command = Some("/restart".to_string());
        }
        "/status" => {
            let model = app.model.as_deref().unwrap_or("default");
            let mut info = format!(
                "Session: {}\nModel: {}\nMessages: {}\nTokens: {}/{} ({:.1}%)\nThinking: {}\nDeliver: {}\nVerbose: {}\nActivation: {}",
                app.session_id,
                model,
                app.messages.len(),
                app.tokens_used,
                app.tokens_max,
                app.token_percent(),
                app.thinking_level,
                if app.deliver { "on" } else { "off" },
                if app.verbose { "on" } else { "off" },
                app.activation_mode,
            );
            if let Some(ref agent) = app.agent_id {
                info.push_str(&format!("\nAgent: {}", agent));
            }
            if let Some(timeout) = app.timeout_seconds {
                info.push_str(&format!("\nTimeout: {}s", timeout));
            }
            if app.cost_usd > 0.0 {
                info.push_str(&format!("\nCost: ${:.4}", app.cost_usd));
            }
            app.add_message("system", &info);
        }
        "/health" => {
            // Check gateway connection status
            let status = match app.connection_status {
                crate::app::ConnectionStatus::Connected => "OK - Connected",
                crate::app::ConnectionStatus::Connecting => "Connecting...",
                crate::app::ConnectionStatus::Disconnected => "Disconnected",
            };
            app.add_message("system", &format!("Gateway health: {}", status));
        }
        "/compact" => {
            app.add_message("system", "Compacting context...");
            app.pending_command = Some("/compact".to_string());
        }
        "/theme" => {
            if let Some(&name) = args.first() {
                match name {
                    "default" | "dark" | "light" | "monokai" | "dracula" => {
                        app.set_theme(name);
                        app.add_message("system", &format!("Theme set to: {}", name));
                        app.status_message = format!("Theme: {}", name);
                    }
                    _ => {
                        app.add_message(
                            "system",
                            "Usage: /theme <default|dark|light|monokai|dracula>",
                        );
                    }
                }
            } else {
                app.cycle_theme();
                app.add_message("system", &format!("Theme: {}", app.theme_name));
                app.status_message = format!("Theme: {}", app.theme_name);
            }
        }
        "/keybind" => {
            // New command to view or set keybindings
            if args.is_empty() {
                // Show all keybindings
                let mut text = "Current keybindings:\n".to_string();
                for (action, bindings) in app.list_keybindings() {
                    for binding in bindings {
                        let mods_str = binding.modifiers.join("+");
                        let key_combo = if mods_str.is_empty() {
                            binding.key.clone()
                        } else {
                            format!("{}+{}", mods_str, binding.key)
                        };
                        text.push_str(&format!("  {} -> {}\n", action, key_combo));
                    }
                }
                app.add_message("system", &text);
            } else if let Some(action) = args.first() {
                if args.len() < 2 {
                    // Show binding for specific action
                    if let Some(bindings) = app.get_keybindings(action) {
                        let combos: Vec<String> = bindings
                            .iter()
                            .map(|b| {
                                let mods = b.modifiers.join("+");
                                if mods.is_empty() {
                                    b.key.clone()
                                } else {
                                    format!("{}+{}", mods, b.key)
                                }
                            })
                            .collect();
                        app.add_message("system", &format!("{}: {}", action, combos.join(", ")));
                    } else {
                        app.add_message("system", &format!("No binding for '{}'", action));
                    }
                } else {
                    // Set new binding: /keybind <action> <modifiers>+<key>
                    // Example: /keybind send Ctrl+Enter
                    let key_combo = args[1..].join("+");
                    let parts: Vec<&str> = key_combo.split('+').collect();
                    let modifiers = if parts.len() > 1 {
                        parts[0..parts.len() - 1]
                            .iter()
                            .map(|s| s.to_string())
                            .collect()
                    } else {
                        Vec::new()
                    };
                    let key = if parts.is_empty() {
                        String::new()
                    } else {
                        parts.last().unwrap_or(&"").to_string()
                    };

                    if key.is_empty() {
                        app.add_message("system", "Invalid key combination");
                    } else {
                        app.set_keybinding(action.to_string(), modifiers.clone(), key.clone());
                        app.status_message = format!(
                            "Bound {} to {}{}{}",
                            action,
                            modifiers.join("+"),
                            if modifiers.is_empty() { "" } else { "+" },
                            key
                        );
                        // Save state
                        if let Err(e) = crate::persistence::save_state(&app.to_saved()) {
                            app.add_message("system", &format!("Failed to save: {}", e));
                        }
                    }
                }
            }
        }
        "/unbind" => {
            if let Some(action) = args.first() {
                if app.remove_keybinding(action) {
                    app.add_message("system", &format!("Unbound '{}'", action));
                    // Save state
                    if let Err(e) = crate::persistence::save_state(&app.to_saved()) {
                        app.add_message("system", &format!("Failed to save: {}", e));
                    }
                } else {
                    app.add_message("system", &format!("No binding for '{}'", action));
                }
            } else {
                app.add_message("system", "Usage: /unbind <action>");
            }
        }
        "/keybindings" => {
            // Show help text summary
            let mut text = "Keyboard shortcuts (customizable with /keybind):\n".to_string();
            // Group by action
            for (action, _) in &[
                ("enter", "Send/Submit"),
                ("escape", "Cancel/Quit"),
                ("force_quit", "Force quit"),
                ("focus_next", "Switch focus"),
                ("cycle_theme", "Cycle theme"),
                ("toggle_multiline", "Toggle input mode"),
                ("edit_last", "Edit last message"),
                ("insert_newline", "Insert newline"),
                ("scroll_up", "Scroll up"),
                ("scroll_down", "Scroll down"),
                ("cursor_left", "Cursor left"),
                ("cursor_right", "Cursor right"),
                ("cursor_home", "Cursor home"),
                ("cursor_end", "Cursor end"),
                ("backspace", "Backspace"),
                ("delete", "Delete"),
            ] {
                if let Some(bindings) = app.get_keybindings(action) {
                    let combos: Vec<String> = bindings
                        .iter()
                        .map(|b| {
                            let mods = b.modifiers.join("+");
                            if mods.is_empty() {
                                b.key.clone()
                            } else {
                                format!("{}+{}", mods, b.key)
                            }
                        })
                        .collect();
                    if !combos.is_empty() {
                        text.push_str(&format!("  {}: {}\n", action, combos.join(", ")));
                    }
                }
            }
            app.add_message("system", &text);
        }
        "/help" => {
            app.add_message(
                "system",
                "Available commands:\n\
                  /new, /reset    - Reset session\n\
                  /clear          - Clear chat\n\
                  /session [id]   - Show/switch session\n\
                  /sessions       - List recent sessions\n\
                  /history        - Load session history\n\
                  /agent [id]     - Show/set agent\n\
                  /model [name]   - Show/set model\n\
                  /think [level]  - Set thinking (off|minimal|low|medium|high|xhigh)\n\
                  /deliver        - Toggle deliver mode\n\
                  /verbose [on|off] - Toggle verbose\n\
                  /usage [mode]   - Set usage display (off|tokens|full)\n\
                  /cost           - Show session cost\n\
                  /timeout [sec]  - Set timeout\n\
                  /activation [m] - Set activation (mention|always)\n\
                  /restart        - Restart gateway\n\
                  /status         - Show session info\n\
                  /health         - Check gateway\n\
                  /compact        - Compact context\n\
                  /theme [name]   - Set/cycle theme\n\
                  /edit           - Edit last user message\n\
                  /regenerate     - Regenerate last response\n\
                  /multiline      - Toggle multi-line input\n\
                  /keybind <action> [combo] - View or set keybinding\n\
                  /unbind <action> - Remove keybinding\n\
                  /keybindings    - Show all keybindings\n\
                  /help           - Show this help",
            );
        }
        _ => {
            app.add_message(
                "system",
                &format!(
                    "Unknown command: {}. Type /help for available commands.",
                    cmd
                ),
            );
        }
    }
}

