use std::sync::Arc;
use std::sync::Mutex as StdMutex;
use std::time::Duration;

use ai::{AgentRequest, GatewayConnection, GatewayMessage};
use app::App;
use crossterm::event::{self, Event};
use persistence::{load_state, save_state};
use ratatui::Terminal;
use tokio::sync::mpsc;
use tokio::sync::Mutex as TokioMutex;

fn main() -> anyhow::Result<()> {
    let saved = load_state();
    let app_state = App::from_saved(saved.clone());
    let app = Arc::new(StdMutex::new(app_state));

    let rt = tokio::runtime::Runtime::new()?;
    rt.block_on(async {
        // Determine gateway token: env var takes precedence over saved state
        let gateway_token = std::env::var("OPENCLAW_GATEWAY_TOKEN")
            .ok()
            .or_else(|| {
                if saved.gateway_token.is_empty() {
                    None
                } else {
                    Some(saved.gateway_token)
                }
            });

        let gateway_url = std::env::var("OPENCLAW_GATEWAY_URL")
            .unwrap_or_else(|_| "ws://127.0.0.1:18789".to_string());

        let (msg_tx, mut msg_rx) = mpsc::channel::<GatewayMessage>(64);

        let mut gateway_conn = GatewayConnection::new(&gateway_url, gateway_token);

        {
            let mut app_guard = app.lock().unwrap();
            app_guard.connection_status = app::ConnectionStatus::Connecting;
            app_guard.status_message = "Connecting...".to_string();
        }

        match gateway_conn.connect().await {
            Ok(_) => {
                let mut app_guard = app.lock().unwrap();
                app_guard.connection_status = app::ConnectionStatus::Connected;
                app_guard.status_message = "Connected".to_string();
            }
            Err(_) => {
                let mut app_guard = app.lock().unwrap();
                app_guard.connection_status = app::ConnectionStatus::Disconnected;
                app_guard.status_message = "Gateway offline - will retry".to_string();
            }
        }

        let gateway = Arc::new(TokioMutex::new(gateway_conn));
        let gateway_clone = gateway.clone();
        let msg_tx_clone = msg_tx.clone();

        tokio::spawn(async move {
            let mut receiver = {
                let mut g = gateway_clone.lock().await;
                g.take_receiver()
            };

            if let Some(rx) = &mut receiver {
                while let Some(msg) = rx.recv().await {
                    if msg_tx_clone.send(msg).await.is_err() {
                        break;
                    }
                }
            }
        });

        let gateway_reconnect = gateway.clone();
        let msg_tx_reconnect = msg_tx.clone();
        tokio::spawn(async move {
            ai::start_reconnect_loop(gateway_reconnect, msg_tx_reconnect).await;
        });

        let mut terminal = ratatui::init();

        let result = run_app(&mut terminal, app.clone(), gateway, &mut msg_rx).await;

        let saved_state = {
            let app_guard = app.lock().unwrap();
            app_guard.to_saved()
        };
        if let Err(e) = save_state(&saved_state) {
            eprintln!("Failed to save state: {}", e);
        }

        ratatui::restore();
        result
    })
}

async fn run_app(
    terminal: &mut Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>,
    app: Arc<StdMutex<App>>,
    gateway: Arc<TokioMutex<GatewayConnection>>,
    msg_rx: &mut mpsc::Receiver<GatewayMessage>,
) -> anyhow::Result<()> {
    loop {
        {
            let app_guard = app.lock().unwrap();
            terminal.draw(|frame| ui::render(frame, &app_guard))?;
        }

        if event::poll(Duration::from_millis(16))? {
            match event::read()? {
                Event::Key(key) => {
                    let mut app_guard = app.lock().unwrap();
                    app::handle_events(&mut app_guard, Event::Key(key))?;
                }
                Event::Resize(_, _) => {}
                _ => {}
            }
        }

        // Sync token to gateway if changed
        let token_opt = {
            let mut app_guard = app.lock().unwrap();
            if app_guard.token_needs_sync {
                app_guard.token_needs_sync = false;
                Some(app_guard.gateway_token.clone())
            } else {
                None
            }
        };
        if let Some(token) = token_opt {
            let mut gw = gateway.lock().await;
            gw.set_token(Some(token));
            // If currently connected, close to force reconnect with new token
            let is_connected = gw.is_connected().await;
            if is_connected {
                gw.close().await;
            }
        }

        while let Ok(msg) = msg_rx.try_recv() {
            let mut app_guard = app.lock().unwrap();
            match msg {
                GatewayMessage::TextDelta { delta, .. } => {
                    app_guard.append_to_last_message(&delta);
                }
                GatewayMessage::TextDone { .. } => {
                    app_guard.finish_streaming();
                    app_guard.status_message = "Ready".to_string();
                }
                GatewayMessage::RunComplete {
                    text,
                    input_tokens,
                    output_tokens,
                    error,
                    ..
                } => {
                    let cost = estimate_cost(&text, input_tokens, output_tokens);

                    if app_guard.is_streaming() {
                        if let Some(last) = app_guard.messages.last_mut() {
                            last.content = text;
                            last.streaming = false;
                            last.input_tokens = input_tokens;
                            last.output_tokens = output_tokens;
                            last.cost = cost;
                        }
                    } else {
                        app_guard.add_message("assistant", &text);
                        app_guard.update_last_message_usage(input_tokens, output_tokens, cost);
                    }
                    app_guard.tokens_used += input_tokens + output_tokens;
                    app_guard.cost_usd += cost;
                    if let Some(e) = error {
                        app_guard.status_message = format!("Error: {}", e);
                    } else {
                        app_guard.status_message = "Ready".to_string();
                    }
                }
                GatewayMessage::Usage { input, output } => {
                    app_guard.tokens_used += input + output;
                }
                GatewayMessage::Connected => {
                    app_guard.connection_status = app::ConnectionStatus::Connected;
                    app_guard.status_message = "Connected".to_string();
                    app_guard.clear_error();
                }
                GatewayMessage::Disconnected => {
                    app_guard.connection_status = app::ConnectionStatus::Disconnected;
                    app_guard.status_message = "Disconnected - retrying...".to_string();
                }
                GatewayMessage::Reconnecting => {
                    app_guard.connection_status = app::ConnectionStatus::Connecting;
                    app_guard.status_message = "Reconnecting...".to_string();
                }
                GatewayMessage::Error(e) => {
                    app_guard.set_error(&format!("Error: {}", e));
                    app_guard.status_message = "Error".to_string();
                }
            }
        }

        // Increment animation tick each frame
        {
            let mut app_guard = app.lock().unwrap();
            app_guard.animation_tick += 1;
        }

        let (pending_msg, pending_cmd) = {
            let mut app_guard = app.lock().unwrap();
            let msg = app_guard.pending_message.take();
            let cmd = app_guard.pending_command.take();
            (msg, cmd)
        };

        if let Some(message) = pending_msg {
            let (session_id, thinking, agent, model, deliver, verbose, timeout, is_connected) = {
                let app_guard = app.lock().unwrap();
                (
                    app_guard.session_id.clone(),
                    app_guard.thinking_level.clone(),
                    app_guard.agent_id.clone(),
                    app_guard.model.clone(),
                    app_guard.deliver,
                    app_guard.verbose,
                    app_guard.timeout_seconds,
                    app_guard.connection_status == app::ConnectionStatus::Connected,
                )
            };

            if is_connected {
                let mut app_guard = app.lock().unwrap();
                app_guard.add_message("user", &message);
                app_guard.start_streaming_message("assistant");
                app_guard.status_message = "Streaming...".to_string();

                let req = build_agent_request(&session_id, &message, &thinking, agent.as_deref(), model.as_deref(), deliver, verbose, timeout);

                let g = gateway.lock().await;
                let _ = g.send(&req).await;
            } else {
                let mut app_guard = app.lock().unwrap();
                app_guard.add_message("system", "Not connected to gateway. Cannot send message.");
            }
        }

        if let Some(cmd) = pending_cmd {
            handle_special_command(&app, &gateway, &cmd).await;
        }

        {
            let app_guard = app.lock().unwrap();
            if !app_guard.running {
                break;
            }
        }
    }

    Ok(())
}

fn build_agent_request(
    session_id: &str,
    message: &str,
    thinking: &str,
    agent: Option<&str>,
    model: Option<&str>,
    deliver: bool,
    verbose: bool,
    timeout: Option<u32>,
) -> AgentRequest {
    let mut req = AgentRequest::new(session_id, message);

    if let Some(a) = agent {
        req = req.with_agent(a);
    }
    if let Some(m) = model {
        req = req.with_model(m);
    }

    req = req.with_thinking(thinking);

    if deliver {
        req = req.with_deliver(true);
    }
    if verbose {
        req = req.with_verbose(true);
    }
    if let Some(t) = timeout {
        req = req.with_timeout(t);
    }

    req
}

async fn handle_special_command(
    app: &Arc<StdMutex<App>>,
    gateway: &Arc<TokioMutex<GatewayConnection>>,
    cmd: &str,
) {
    match cmd {
        "/restart" => {
            let result = std::process::Command::new("openclaw")
                .args(["gateway", "restart"])
                .output();

            let mut app_guard = app.lock().unwrap();
            match result {
                Ok(output) => {
                    if output.status.success() {
                        app_guard.add_message("system", "Gateway restart initiated.");
                        app_guard.status_message = "Restarting...".to_string();
                    } else {
                        let stderr = String::from_utf8_lossy(&output.stderr);
                        app_guard.add_message("system", &format!("Restart failed: {}", stderr));
                    }
                }
                Err(e) => {
                    app_guard.add_message("system", &format!("Failed to restart: {}", e));
                }
            }
        }
        "/compact" => {
            let session_id = {
                let app_guard = app.lock().unwrap();
                app_guard.session_id.clone()
            };

            let req = AgentRequest::new(&session_id, "/compact");
            let g = gateway.lock().await;
            let _ = g.send(&req).await;
        }
        "/history" => {
            let session_id = {
                let app_guard = app.lock().unwrap();
                app_guard.session_id.clone()
            };

            match ai::OpenClawClient::get_session_history(&session_id) {
                Ok(history) => {
                    let mut app_guard = app.lock().unwrap();
                    if history.is_empty() {
                        app_guard.add_message("system", "No history found for this session.");
                    } else {
                        app_guard.add_message("system", &format!("Loaded {} messages from history.", history.len()));
                        for msg in history {
                            app_guard.add_message(&msg.role, &msg.content);
                        }
                    }
                }
                Err(e) => {
                    let mut app_guard = app.lock().unwrap();
                    app_guard.add_message("system", &format!("Failed to load history: {}", e));
                }
            }
        }
        "/token" => {
            // Show token input modal
            let mut app_guard = app.lock().unwrap();
            app_guard.showing_token_input = true;
            app_guard.token_input.clear();
            app_guard.token_error = None;
            app_guard.status_message = "Enter gateway token:".to_string();
        }
        _ => {}
    }
}

fn estimate_cost(_text: &str, input_tokens: u64, output_tokens: u64) -> f64 {
    if input_tokens == 0 && output_tokens == 0 {
        return 0.0;
    }
    let input_cost = (input_tokens as f64 / 1_000_000.0) * 3.0;
    let output_cost = (output_tokens as f64 / 1_000_000.0) * 15.0;
    input_cost + output_cost
}

