fn main() -> anyhow::Result<()> {
    let saved = load_state();
    let mut config = load_config();

    let rt = tokio::runtime::Runtime::new()?;
    rt.block_on(async {
        // Determine gateway URL: env > config > default
        let gateway_url = std::env::var("OPENROUTER_BASE_URL")
            .ok()
            .or_else(|| config.openrouter_base_url.clone())
            .or_else(|| std::env::var("AI_GATEWAY_URL").ok())
            .or_else(|| config.ai_gateway_url.clone())
            .or_else(|| std::env::var("OPENCLAW_GATEWAY_URL").ok())
            .unwrap_or_else(|| "http://127.0.0.1:8000".to_string());

        // Determine gateway API key: env > config > none
        let gateway_token = std::env::var("OPENROUTER_API_KEY")
            .ok()
            .or_else(|| config.openrouter_api_key.clone())
            .or_else(|| std::env::var("AI_GATEWAY_TOKEN").ok())
            .or_else(|| config.ai_gateway_key.clone())
            .or_else(|| std::env::var("OPENCLAW_GATEWAY_TOKEN").ok());

        // Determine backend display name
        let backend_name = if gateway_url.contains("openrouter.ai") {
            "OpenRouter"
        } else {
            "OpenAI"
        };

        // Determine which model to use for rate lookup (from env > config > default)
        let configured_model = std::env::var("OPENROUTER_MODEL")
            .ok()
            .or_else(|| config.openrouter_model.clone())
            .unwrap_or_else(|| "openrouter/auto".to_string());

        // Determine cost rates: env > config > defaults
        let cost_input_rate = std::env::var("AI_COST_INPUT_PER_MILLION")
            .ok()
            .and_then(|s| s.parse::<f64>().ok())
            .or_else(|| config.cost_input_per_million)
            .unwrap_or(3.0);
        let cost_output_rate = std::env::var("AI_COST_OUTPUT_PER_MILLION")
            .ok()
            .and_then(|s| s.parse::<f64>().ok())
            .or_else(|| config.cost_output_per_million)
            .unwrap_or(15.0);

        // Auto-fetch rates from OpenRouter if applicable
        let is_openrouter = backend_name == "OpenRouter";
        let has_api_key = gateway_token.is_some();
        let is_auto_model = configured_model.contains("auto");

        // Use mutable final rates, defaulting to the rates we just determined
        let mut final_input_rate = cost_input_rate;
        let mut final_output_rate = cost_output_rate;

        if is_openrouter && has_api_key && !is_auto_model {
            let current_time = models::current_timestamp();
            let cache_valid = config.rate_fetched_at.map_or(false, |fetched_at| {
                current_time - fetched_at < 86400 // 24 hours
            });
            let cache_matches = config.cached_model_id.as_ref() == Some(&configured_model);

            if cache_valid && cache_matches {
                // Try to use cached rates
                if let (Some(cached_input), Some(cached_output)) = (
                    config.cached_openrouter_rate_input,
                    config.cached_openrouter_rate_output,
                ) {
                    final_input_rate = cached_input;
                    final_output_rate = cached_output;
                } else {
                    // Cache incomplete, fetch fresh
                    if let Ok(Some((input, output))) = models::fetch_rate_for_model(
                        gateway_token.as_deref(),
                        &gateway_url,
                        &configured_model,
                    ).await
                    {
                        final_input_rate = input;
                        final_output_rate = output;
                        config.cached_openrouter_rate_input = Some(input);
                        config.cached_openrouter_rate_output = Some(output);
                        config.cached_model_id = Some(configured_model.clone());
                        config.rate_fetched_at = Some(current_time);
                        config.openrouter_model = Some(configured_model.clone());
                    }
                }
            } else {
                // Cache stale or mismatched - fetch fresh
                if let Ok(Some((input, output))) = models::fetch_rate_for_model(
                    gateway_token.as_deref(),
                    &gateway_url,
                    &configured_model,
                ).await
                {
                    final_input_rate = input;
                    final_output_rate = output;
                    config.cached_openrouter_rate_input = Some(input);
                    config.cached_openrouter_rate_output = Some(output);
                    config.cached_model_id = Some(configured_model.clone());
                    config.rate_fetched_at = Some(current_time);
                    config.openrouter_model = Some(configured_model.clone());
                }
            }
        }

        let mut app_state = App::from_saved(saved.clone());
        app_state.backend_name = backend_name.to_string();
        app_state.cost_input_rate = final_input_rate;
        app_state.cost_output_rate = final_output_rate;
        app_state.api_key = gateway_token.clone().unwrap_or_default();
        let app = Arc::new(StdMutex::new(app_state));

        let (msg_tx, mut msg_rx) = mpsc::channel::<GatewayMessage>(64);

        let mut gateway_conn = GatewayConnection::new(&gateway_url, gateway_token);

        {
            let mut app_guard = app.lock().unwrap();
            app_guard.connection_status = app::ConnectionStatus::Connecting;
            app_guard.status_message = "Connecting...".to_string();
        }

        match gateway_conn.connect().await {
            Ok(_) => {
                let mut app_guard = app.lock().unwrap();
                app_guard.connection_status = app::ConnectionStatus::Connected;
                app_guard.status_message = "Connected".to_string();
            }
            Err(_) => {
                let mut app_guard = app.lock().unwrap();
                app_guard.connection_status = app::ConnectionStatus::Disconnected;
                app_guard.status_message = "Gateway offline - will retry".to_string();
            }
        }

        let gateway = Arc::new(TokioMutex::new(gateway_conn));
        let gateway_clone = gateway.clone();
        let msg_tx_clone = msg_tx.clone();

        tokio::spawn(async move {
            let mut receiver = {
                let mut g = gateway_clone.lock().await;
                g.take_receiver()
            };

            if let Some(rx) = &mut receiver {
                while let Some(msg) = rx.recv().await {
                    if msg_tx_clone.send(msg).await.is_err() {
                        break;
                    }
                }
            }
        });

        let gateway_reconnect = gateway.clone();
        let msg_tx_reconnect = msg_tx.clone();
        tokio::spawn(async move {
            ai::start_reconnect_loop(gateway_reconnect, msg_tx_reconnect).await;
        });

        let mut terminal = ratatui::init();

        let result = run_app(&mut terminal, app.clone(), gateway, &mut msg_rx).await;

        let saved_state = {
            let app_guard = app.lock().unwrap();
            app_guard.to_saved()
        };
        if let Err(e) = save_state(&saved_state) {
            eprintln!("Failed to save state: {}", e);
        }

        // Persist updated config (including cached rates, model, etc.)
        if let Err(e) = save_config(&config) {
            eprintln!("Failed to save config: {}", e);
        }

        ratatui::restore();
        result
    })
}

