        }
        "/history" => {
            // History loading not directly supported with OpenAI API
            let mut app_guard = app.lock().unwrap();
            app_guard.add_message(
                "system",
                "Session history loading not available with OpenAI backend. Each conversation is stateless.",
            );
        }
        "/token" => {
            // Show API key input modal
            let mut app_guard = app.lock().unwrap();
            app_guard.showing_api_key_input = true;
            app_guard.api_key_input.clear();
            app_guard.api_key_error = None;
            app_guard.status_message = "Enter API key:".to_string();
        }
        _ => {}
    }
}

