use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Style},
    text::{Span, Text},
    widgets::{Block, Borders, Gauge, Paragraph},
    Frame,
};

use crate::app::{App, Focus};

use super::{chat, input};

pub fn render(frame: &mut Frame, app: &App) {
    let area = frame.area();

    // Swiss Brutalist asymmetric layout
    let outer_chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(1)
        .constraints([
            Constraint::Length(1), // Header
            Constraint::Min(10),   // Body (chat + sidebar)
            Constraint::Length(1), // Status bar
            Constraint::Length(3), // Input
        ])
        .split(area);

    render_header(frame, app, outer_chunks[0]);
    render_body(frame, app, outer_chunks[1]);
    render_status_bar(frame, app, outer_chunks[2]);

    let input_area = outer_chunks[3];
    input::render(frame, app, input_area);

    // Command palette overlay (positioned above cursor)
    if app.showing_command_palette {
        // Calculate cursor position within input area
        let (cursor_x, _) =
            input::calculate_cursor_position(&app.input, app.input_cursor, input_area);
        render_command_palette(frame, app, input_area, cursor_x);
    }

    // Token input modal
    if app.showing_token_input {
        render_token_modal(frame, app, area);
    }

    if let Some(ref error) = app.error {
        render_error_popup(frame, app, error.message.clone(), error.is_warning);
    }
}

fn render_body(frame: &mut Frame, app: &App, area: Rect) {
    let body_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(70), // Chat area (70%)
            Constraint::Min(20),        // Sidebar (min 20)
        ])
        .split(area);

    // Render chat with bold border
    chat::render(frame, app, body_chunks[0]);

    // Render separator line
    let separator = Rect {
        x: body_chunks[0].x + body_chunks[0].width,
        y: body_chunks[0].y,
        width: 1,
        height: body_chunks[0].height,
    };
    // Draw a vertical line by rendering a block with left+right borders
    let line_block = Block::default()
        .borders(Borders::LEFT | Borders::RIGHT)
        .border_style(Style::default().fg(app.theme.divider_color));
    frame.render_widget(line_block, separator);

    // Render stats sidebar
    render_sidebar(frame, app, body_chunks[1]);
}

fn render_sidebar(frame: &mut Frame, app: &App, area: Rect) {
    let title = Span::styled(
        " Stats ",
        Style::default().fg(app.theme.accent_color).bold(),
    );

    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(app.theme.border_color));

    let inner = block.inner(area);
    frame.render_widget(block, area);

    let widget_area = inner;

    let connection_status = match app.connection_status {
        crate::app::ConnectionStatus::Connected => ("●", "Connected", app.theme.user_color),
        crate::app::ConnectionStatus::Connecting => ("◐", "Connecting", app.theme.system_color),
        crate::app::ConnectionStatus::Disconnected => ("○", "Offline", app.theme.muted_color),
    };

    let mut y_offset = 0;

    // Connection status
    let conn_text = Text::from(Span::styled(
        format!("{} {}", connection_status.0, connection_status.1),
        Style::default().fg(connection_status.2),
    ));
    frame.render_widget(
        Paragraph::new(conn_text),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Separator
    let separator_text = Text::from(Span::styled(
        "─".repeat(widget_area.width as usize),
        Style::default().fg(app.theme.divider_color),
    ));
    frame.render_widget(
        Paragraph::new(separator_text),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Token usage gauge
    let percent = app.token_percent();
    let gauge = Gauge::default()
        .block(Block::default().borders(Borders::NONE))
        .gauge_style(Style::default().fg(app.theme.accent_color))
        .label(Span::styled(
            format!("Tokens: {}/{}", app.tokens_used, app.tokens_max),
            Style::default().fg(app.theme.muted_color),
        ))
        .percent(percent as u16);
    y_offset += 2;

    // Token percentage
    let percent_text = Text::from(Span::styled(
        format!("{:.1}%", percent),
        Style::default().fg(if percent > 80.0 {
            app.theme.error_color
        } else if percent > 50.0 {
            app.theme.system_color
        } else {
            app.theme.user_color
        }),
    ));
    frame.render_widget(
        Paragraph::new(percent_text),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Separator
    let separator_text = Text::from(Span::styled(
        "─".repeat(widget_area.width as usize),
        Style::default().fg(app.theme.divider_color),
    ));
    frame.render_widget(
        Paragraph::new(separator_text),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Cost
    if app.cost_usd > 0.0 {
        let cost_text = Text::from(Span::styled(
            format!("${:.4}", app.cost_usd),
            Style::default().fg(app.theme.user_color),
        ));
        frame.render_widget(
            Paragraph::new(cost_text),
            Rect {
                x: widget_area.x,
                y: widget_area.y + y_offset,
                width: widget_area.width,
                height: 1,
            },
        );
        y_offset += 2;
    }

    // Thinking level
    let thinking_text = Text::from(Span::styled(
        format!("Think: {}", app.thinking_level),
        Style::default().fg(app.theme.system_color),
    ));
    frame.render_widget(
        Paragraph::new(thinking_text),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Verbose flag
    if app.verbose {
        let verbose_text = Text::from(Span::styled(
            "VERBOSE",
            Style::default().fg(app.theme.system_color),
        ));
        frame.render_widget(
            Paragraph::new(verbose_text),
            Rect {
                x: widget_area.x,
                y: widget_area.y + y_offset,
                width: widget_area.width,
                height: 1,
            },
        );
        y_offset += 2;
    }

    // Session info (compact)
    let session_text = Text::from(Span::styled(
        format!(
            "Session: {}",
            &app.session_id[..app.session_id.len().min(8)]
        ),
        Style::default().fg(app.theme.muted_color),
    ));
    frame.render_widget(
        Paragraph::new(session_text),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
}

fn render_error_popup(frame: &mut Frame, app: &App, message: String, is_warning: bool) {
    let area = frame.area();
    let popup_area = Rect {
        x: area.width.saturating_sub(60) / 2,
        y: area.height.saturating_sub(5) / 2,
        width: 60.min(area.width.saturating_sub(4)),
        height: 5.min(area.height.saturating_sub(4)),
    };

    let color = if is_warning {
        app.theme.system_color
    } else {
        app.theme.error_color
    };

    let block = Block::default()
        .title(if is_warning { " Warning " } else { " Error " })
        .borders(Borders::ALL)
        .border_style(Style::default().fg(color));

    let paragraph = Paragraph::new(message)
        .block(block)
        .style(Style::default().fg(color));

    frame.render_widget(paragraph, popup_area);
}

fn render_header(frame: &mut Frame, app: &App, area: Rect) {
    let (indicator, indicator_color) = app.connection_indicator();

    let conn = Span::styled(indicator, Style::default().fg(indicator_color).bold());
    let title = Span::styled(
        " OpenClaw TUI ",
        Style::default().fg(app.theme.accent_color).bold(),
    );

    let session = Span::styled(
        format!(" [{}] ", app.session_id),
        Style::default().fg(app.theme.user_color),
    );

    let model = if let Some(ref m) = app.model {
        Span::styled(
            format!("{} ", m),
            Style::default().fg(app.theme.assistant_color),
        )
    } else {
        Span::raw("")
    };

    let agent = if let Some(ref a) = app.agent_id {
        Span::styled(
            format!("agent:{} ", a),
            Style::default().fg(app.theme.muted_color),
        )
    } else {
        Span::raw("")
    };

    let deliver = if app.deliver {
        Span::styled(
            "DELIVER ",
            Style::default().fg(app.theme.error_color).bold(),
        )
    } else {
        Span::raw("")
    };

    let theme_tag = Span::styled(
        format!("[{}] ", app.theme_name),
        Style::default().fg(app.theme.accent_color),
    );

    let mode_tag = match app.input_mode {
        crate::app::InputMode::MultiLine => {
            Span::styled("[ML] ", Style::default().fg(app.theme.system_color))
        }
        _ => Span::raw(""),
    };

    let status = Span::styled(
        format!("| {} ", app.status_message),
        Style::default().fg(app.theme.muted_color),
    );

    let help = Span::styled(
        "Ctrl+N:Switch | Ctrl+T:Theme | /help",
        Style::default().fg(app.theme.divider_color),
    );

    let paragraph = Paragraph::new(vec![ratatui::text::Line::from(vec![
