    let paragraph = Paragraph::new(vec![ratatui::text::Line::from(vec![
        tokens,
        percent_span,
        separator,
        thinking,
        verbose,
        cost,
        timeout,
    ])]);
    frame.render_widget(paragraph, area);
}

fn render_command_palette(frame: &mut Frame, app: &App, anchor: Rect, cursor_x: u16) {
    let area = frame.area();

    // Get filtered commands
    let commands = {
        let filter = &app.command_filter;
        if filter.is_empty() || filter == "/" {
            crate::app::COMMANDS.to_vec()
        } else {
            crate::app::COMMANDS
                .iter()
                .filter(|(cmd, _)| cmd.starts_with(filter))
                .copied()
                .collect()
        }
    };

    if commands.is_empty() {
        return;
    }

    // Determine dimensions
    let max_width = 60u16.min(area.width.saturating_sub(4));
    let max_height = 15u16.min(area.height.saturating_sub(4));

    // Calculate needed width and height
    let title_len = "Commands".len() as u16;
    let max_cmd_desc_len = commands
        .iter()
        .map(|(cmd, desc)| cmd.len() + 2 + desc.len())
        .max()
        .unwrap_or(0) as u16;
    let needed_width = (title_len.max(max_cmd_desc_len) + 4) as u16; // padding
    let needed_height = (commands.len() + 2) as u16; // title + commands + border

    let width = needed_width
        .min(max_width)
        .min(area.width.saturating_sub(4));
    let height = needed_height
        .min(max_height)
        .min(area.height.saturating_sub(4));

    // Position above cursor (left-aligned with cursor), ensuring it stays on screen
    let mut x = anchor.x + cursor_x.saturating_sub(width / 2);
    if x + width > area.width {
        x = area.width.saturating_sub(width);
    }
    if x < anchor.x {
        x = anchor.x;
    }
    let y = anchor.y.saturating_sub(height);

    let popup_area = Rect {
        x,
        y,
        width,
        height,
    };

    let title = Span::styled(
        " Commands ",
        Style::default().fg(app.theme.accent_color).bold(),
    );

    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(app.theme.border_color));

    let inner = block.inner(popup_area);
    frame.render_widget(block, popup_area);

    // Render commands list
    for (i, (cmd, desc)) in commands.iter().enumerate() {
        if i >= inner.height as usize {
            break;
        }
        let line_y = inner.y + i as u16;
        let is_selected = i == app.command_selection;

        let line = ratatui::text::Line::from(vec![
            Span::raw("  "),
            Span::styled(
                *cmd,
                Style::default()
                    .fg(if is_selected {
                        app.theme.accent_color
                    } else {
                        app.theme.user_color
                    })
                    .bold(),
            ),
            Span::raw(" - "),
            Span::styled(
                *desc,
                Style::default().fg(if is_selected {
                    app.theme.accent_color
                } else {
                    app.theme.muted_color
                }),
            ),
        ]);

        frame.render_widget(
            Paragraph::new(line),
            Rect {
                x: inner.x,
                y: line_y,
                width: inner.width,
                height: 1,
            },
        );
    }
}

fn render_token_modal(frame: &mut Frame, app: &App, area: Rect) {
    // Determine dimensions
    let width = 60u16.min(area.width.saturating_sub(4));
    let height = 7u16.min(area.height.saturating_sub(4));

    // Center the modal
    let x = area.x + (area.width - width) / 2;
    let y = area.y + (area.height - height) / 2;

    let modal_area = Rect {
        x,
