        .border_style(Style::default().fg(app.theme.border_color))
        .style(Style::default().bg(app.theme.muted_color));

    let inner = block.inner(modal_area);
    frame.render_widget(block, modal_area);

    // Instruction text
    let instruction = ratatui::text::Line::from(Span::raw("Enter your OpenClaw gateway token:"));
    frame.render_widget(
        Paragraph::new(instruction),
        Rect {
            x: inner.x,
            y: inner.y,
            width: inner.width,
            height: 1,
        },
    );

    // Token input field (masked with asterisks)
    let masked_input = "*".repeat(app.token_input.len());
    let cursor_pos = if app.token_cursor < masked_input.len() {
        app.token_cursor as u16
    } else {
        masked_input.len() as u16
    };

    let input_line = ratatui::text::Line::from(Span::raw(masked_input));
    let input_area = Rect {
        x: inner.x,
        y: inner.y + 1,
        width: inner.width,
        height: 1,
    };
    frame.render_widget(Paragraph::new(input_line), input_area);

    // Render cursor position (simple block cursor)
    if app.showing_token_input {
        let cursor_x = input_area.x + cursor_pos;
        if cursor_x < input_area.x + input_area.width {
            frame.render_widget(
                Paragraph::new(Span::styled(
                    " ",
                    Style::default()
                        .fg(app.theme.accent_color)
                        .bg(app.theme.accent_color),
                )),
                Rect {
                    x: cursor_x,
                    y: input_area.y,
                    width: 1,
                    height: 1,
                },
            );
        }
    }

    // Error message if any
    if let Some(ref err) = app.token_error {
        let error_line = ratatui::text::Line::from(Span::styled(
            err,
            Style::default().fg(app.theme.error_color),
        ));
        frame.render_widget(
            Paragraph::new(error_line),
            Rect {
                x: inner.x,
                y: inner.y + 2,
                width: inner.width,
                height: 1,
            },
        );
    }

    // Help text
    let help_line = ratatui::text::Line::from(Span::raw("Press Enter to save, Esc to cancel"));
    frame.render_widget(
        Paragraph::new(help_line),
        Rect {
            x: inner.x,
            y: inner.y + 3,
            width: inner.width,
            height: 1,
