use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
    widgets::{Block, Borders, Gauge, Paragraph, Scrollbar, ScrollbarOrientation, ScrollbarState},
    Frame,
};

use crate::app::{App, Focus, UsageMode};

use super::{chat, input};

pub fn render(frame: &mut Frame, app: &App) {
    let area = frame.area();

    // Cyberpunk asymmetric layout with neon glow effects
    let outer_chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(1)
        .constraints([
            Constraint::Length(2), // Header with animated neon title
            Constraint::Min(10),   // Body with glitch effects
            Constraint::Length(1), // Status bar with pulse effects
            Constraint::Length(3), // Input with neon border
        ])
        .split(area);

    render_cyberpunk_header(frame, app, outer_chunks[0]);
    render_cyberbody(frame, app, outer_chunks[1]);
    render_neon_status_bar(frame, app, outer_chunks[2]);

    let input_area = outer_chunks[3];
    input::render(frame, app, input_area);

    // Command palette overlay (positioned above cursor)
    if app.showing_command_palette {
        // Calculate cursor position within input area
        let (cursor_x, _) =
            input::calculate_cursor_position(&app.input, app.input_cursor, input_area);
        render_command_palette(frame, app, input_area, cursor_x);
    }

    // API key input modal
    if app.showing_api_key_input {
        render_api_key_modal(frame, app, area);
    }

    if let Some(ref error) = app.error {
        render_error_popup(frame, app, error.message.clone(), error.is_warning);
    }
}

fn render_cyberbody(frame: &mut Frame, app: &App, area: Rect) {
    let body_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(70), // Chat area (70%)
            Constraint::Min(20),        // Sidebar (min 20)
        ])
        .split(area);

    // Render chat area with cyberpunk border effect
    let chat_block = Block::default().borders(Borders::ALL).border_style(
        Style::default()
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD),
    );
    let chat_inner = chat_block.inner(body_chunks[0]);
    frame.render_widget(chat_block, body_chunks[0]);

    // Render chat content with glitch effect
    chat::render(frame, app, chat_inner);

    // Render animated neon separator line
    let separator = Rect {
        x: body_chunks[0].x + body_chunks[0].width,
        y: body_chunks[0].y,
        width: 1,
        height: body_chunks[0].height,
    };
    // Draw a vertical neon line with pulse effect
    let pulse_char = if (app.animation_tick % 6) < 3 {
        "█"
    } else {
        "▓"
    };
    let line_block = Block::default()
        .borders(Borders::LEFT | Borders::RIGHT)
        .border_style(
            Style::default()
                .fg(Color::Magenta)
                .add_modifier(Modifier::BOLD),
        );
    frame.render_widget(line_block, separator);

    // Very subtle scanline effect over separator (much slower)
    let scanline_y = ((app.animation_tick / 16) % body_chunks[0].height as u64) as u16;
    if scanline_y < separator.height {
        frame.render_widget(
            Paragraph::new(Span::raw(pulse_char)),
            Rect {
                x: separator.x,
                y: separator.y + scanline_y,
                width: 1,
                height: 1,
            },
        );
    }

    // Render cyberpunk stats sidebar
    render_cyberpunk_sidebar(frame, app, body_chunks[1]);
}

