        .min(area.height.saturating_sub(4));

    // Position above cursor (left-aligned with cursor), ensuring it stays on screen
    let mut x = anchor.x + cursor_x.saturating_sub(width / 2);
    if x + width > area.width {
        x = area.width.saturating_sub(width);
    }
    if x < anchor.x {
        x = anchor.x;
    }
    let y = anchor.y.saturating_sub(height);

    let popup_area = Rect {
        x,
        y,
        width,
        height,
    };

    let title = Span::styled(
        " Commands ",
        Style::default().fg(app.theme.accent_color).bold(),
    );

    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(app.theme.border_color));

    let inner = block.inner(popup_area);
    frame.render_widget(block, popup_area);

    // Render commands list
    for (i, (cmd, desc)) in commands.iter().enumerate() {
        if i >= inner.height as usize {
            break;
        }
        let line_y = inner.y + i as u16;
        let is_selected = i == app.command_selection;

        let line = ratatui::text::Line::from(vec![
            Span::raw("  "),
            Span::styled(
                *cmd,
                Style::default()
                    .fg(if is_selected {
                        app.theme.accent_color
                    } else {
                        app.theme.user_color
                    })
                    .bold(),
            ),
            Span::raw(" - "),
            Span::styled(
                *desc,
                Style::default().fg(if is_selected {
                    app.theme.accent_color
                } else {
                    app.theme.muted_color
                }),
            ),
        ]);

        frame.render_widget(
            Paragraph::new(line),
            Rect {
                x: inner.x,
                y: line_y,
                width: inner.width,
                height: 1,
            },
        );
    }
}

fn render_cyberpunk_sidebar(frame: &mut Frame, app: &App, area: Rect) {
    // Cyberpunk sidebar with data stream effects
    let title = Span::styled(
        " ⚡ SYSTEM METRICS ",
        Style::default()
            .fg(app.theme.accent_color)
            .add_modifier(Modifier::BOLD),
    );

    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        )
        .style(Style::default().bg(Color::Black));

    let inner = block.inner(area);
    frame.render_widget(block, area);

    let widget_area = inner;

    // Connection status indicator (no glitch, just solid)
    let status_char = match app.connection_status {
        crate::app::ConnectionStatus::Connected => "█",
        crate::app::ConnectionStatus::Connecting => "◐",
        crate::app::ConnectionStatus::Disconnected => "○",
    };

    let (status_text, status_color) = match app.connection_status {
        crate::app::ConnectionStatus::Connected => ("ONLINE", Color::Green),
        crate::app::ConnectionStatus::Connecting => ("CONNECTING...", Color::Yellow),
        crate::app::ConnectionStatus::Disconnected => ("OFFLINE", Color::Red),
    };

    let mut y_offset = 0;

    // System status header
    let status_line = Line::from(vec![
        Span::styled("◉", Style::default().fg(app.theme.accent_color).bold()),
        Span::raw(" "),
        Span::styled("SYSTEM STATUS", Style::default().fg(Color::White).bold()),
    ]);
    frame.render_widget(
        Paragraph::new(status_line),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Connection status line
    let conn_line = Line::from(vec![
        Span::raw("  ├─ "),
        Span::styled(status_char, Style::default().fg(status_color).bold()),
        Span::raw(" "),
        Span::styled(status_text, Style::default().fg(Color::White).bold()),
    ]);
    frame.render_widget(
        Paragraph::new(conn_line),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Separator with very subtle animation
    let sep_char = if (app.animation_tick % 80) < 40 {
        "═"
    } else {
        "─"
    };
    let separator_text = Text::from(Span::styled(
        format!("{}", sep_char.repeat(widget_area.width as usize - 4)),
        Style::default()
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD),
    ));
    frame.render_widget(
        Paragraph::new(separator_text),
        Rect {
            x: widget_area.x + 2,
            y: widget_area.y + y_offset,
            width: widget_area.width - 4,
            height: 1,
        },
    );
    y_offset += 2;

    // Data usage section header
    let data_header = Line::from(vec![
        Span::styled("◈", Style::default().fg(app.theme.accent_color).bold()),
        Span::raw(" "),
        Span::styled("DATA STREAM", Style::default().fg(Color::White).bold()),
    ]);
    frame.render_widget(
        Paragraph::new(data_header),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Token usage with graphical representation
    let percent = app.token_percent();
    let bar_width = ((widget_area.width as f64 - 8.0) * (percent / 100.0)) as u16;
    let bar_color = if percent > 80.0 {
        Color::Red
    } else if percent > 50.0 {
        Color::Yellow
    } else {
        Color::Green
    };

    // Usage bar with blocks
    let bar = format!(
        "█{}",
        "░".repeat((widget_area.width - 8).saturating_sub(bar_width) as usize)
    );
    let bar_line = Line::from(vec![
        Span::raw("  ├─ "),
        Span::styled(
            &bar[..bar_width as usize],
            Style::default().fg(bar_color).bold(),
        ),
        Span::styled(
            &bar[bar_width as usize..],
            Style::default().fg(Color::DarkGray),
        ),
        Span::raw(" "),
    ]);
    frame.render_widget(
        Paragraph::new(bar_line),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 1;

    // Token counts
    let tokens_line = Line::from(vec![
        Span::raw("  └─ "),
        Span::styled(
            format!("{}", app.tokens_used),
            Style::default().fg(app.theme.user_color).bold(),
        ),
        Span::raw("/"),
        Span::styled(
            format!("{}", app.tokens_max),
            Style::default().fg(app.theme.muted_color),
        ),
        Span::raw(" tokens"),
    ]);
    frame.render_widget(
        Paragraph::new(tokens_line),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Separator
    let sep_char2 = if (app.animation_tick % 80) < 40 {
        "═"
    } else {
        "─"
    };
    let separator_text2 = Text::from(Span::styled(
        format!("{}", sep_char2.repeat(widget_area.width as usize - 4)),
        Style::default()
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD),
    ));
    frame.render_widget(
        Paragraph::new(separator_text2),
        Rect {
            x: widget_area.x + 2,
            y: widget_area.y + y_offset,
            width: widget_area.width - 4,
            height: 1,
        },
    );
    y_offset += 2;

    // Cost display with neon effect
    if app.cost_usd > 0.0 {
        let cost_header = Line::from(vec![
            Span::styled("◉", Style::default().fg(app.theme.accent_color).bold()),
            Span::raw(" "),
            Span::styled("COST TRACKING", Style::default().fg(Color::White).bold()),
        ]);
        frame.render_widget(
            Paragraph::new(cost_header),
            Rect {
                x: widget_area.x,
                y: widget_area.y + y_offset,
                width: widget_area.width,
                height: 1,
            },
        );
        y_offset += 2;

        let cost_line = Line::from(vec![
            Span::raw("  └─ 💲 "),
            Span::styled(
                format!("${:.4}", app.cost_usd),
                Style::default().fg(app.theme.user_color).bold(),
            ),
        ]);
        frame.render_widget(
            Paragraph::new(cost_line),
            Rect {
                x: widget_area.x,
                y: widget_area.y + y_offset,
                width: widget_area.width,
                height: 1,
            },
        );
        y_offset += 2;
    }

    // Configuration section
    let config_header = Line::from(vec![
        Span::styled("◈", Style::default().fg(app.theme.accent_color).bold()),
        Span::raw(" "),
        Span::styled("CONFIG", Style::default().fg(Color::White).bold()),
    ]);
    frame.render_widget(
        Paragraph::new(config_header),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 2;

    // Thinking level
    let think_line = Line::from(vec![
        Span::raw("  ├─ "),
        Span::styled("THINK:", Style::default().fg(app.theme.system_color).bold()),
        Span::raw(" "),
        Span::styled(&app.thinking_level, Style::default().fg(Color::White)),
    ]);
    frame.render_widget(
        Paragraph::new(think_line),
        Rect {
            x: widget_area.x,
            y: widget_area.y + y_offset,
            width: widget_area.width,
            height: 1,
        },
    );
    y_offset += 1;

    // Verbose flag
    if app.verbose {
        let verbose_line = Line::from(vec![
            Span::raw("  └─ "),
            Span::styled(
                "✧ VERBOSE",
                Style::default().fg(app.theme.system_color).bold(),
            ),
        ]);
        frame.render_widget(
            Paragraph::new(verbose_line),
            Rect {
                x: widget_area.x,
                y: widget_area.y + y_offset,
                width: widget_area.width,
                height: 1,
            },
        );
        y_offset += 1;
    }

    // Session info at bottom
    if y_offset + 2 < widget_area.height {
        let session_y = widget_area.y + widget_area.height - 2;
        let session_line = Line::from(vec![
            Span::styled("◻", Style::default().fg(Color::DarkGray)),
            Span::raw(" "),
            Span::styled(
                format!("ID: {}", &app.session_id[..app.session_id.len().min(12)]),
                Style::default().fg(Color::DarkGray),
            ),
        ]);
        frame.render_widget(
            Paragraph::new(session_line),
            Rect {
                x: widget_area.x,
                y: session_y,
                width: widget_area.width,
                height: 1,
            },
        );
    }
}
